import Foundation

struct AirplaneAsset {
    static let base64ImagePlane = ""
    static let base64ImageUfo = ""
    static let base64ImageRocket = ""
    static let base64ImageAirship = ""
    
    static func getBase64Image(for style: Int) -> String {
        switch style {
        case 1:  return base64ImageUfo
        case 2:  return base64ImageRocket
        case 3:  return base64ImageAirship
        default: return base64ImagePlane
        }
    }
}
